import networkx as nx
from openai import OpenAI

client = OpenAI()
G = nx.Graph()

def add_edge(a: str, b: str, rel: str):
    G.add_edge(a, b, rel=rel)

def neighbors_ctx(entity: str, hops: int = 2) -> str:
    if entity not in G:
        return ""
    sub = nx.ego_graph(G, entity, radius=hops)
    return "\n".join(f"{u} --{d['rel']}--> {v}" for u, v, d in sub.edges(data=True))

def ask(entity: str, q: str) -> str:
    ctx = neighbors_ctx(entity)
    r = client.chat.completions.create(model="{{model_name}}",
        messages=[{"role": "user", "content": f"KG:\n{ctx}\nQ: {q}"}])
    return r.choices[0].message.content
